import { test } from 'node:test';
import assert from 'node:assert/strict';
import { sum } from './sum.mjs';
test('sum',()=>{assert.equal(sum([1,2,3]),6);assert.equal(sum([]),0);assert.equal(sum([-2,2]),0)});

