import { createServer } from 'node:http';
const html = '<!doctype html><title>Counter</title><button id="add">Add</button><output id="value">0</output><script>document.querySelector("#add").onclick=()=>{document.querySelector("#value").value=String(Number(document.querySelector("#value").value)+1)}</script>';
createServer((req,res)=>{res.setHeader('content-type','text/html');res.end(html)}).listen(Number(process.env.PORT || 8080),'0.0.0.0');
